"""Structured temporal candidate policy with safety gating and bounded hysteresis."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop immediately when confidence is low or collision risk is elevated."""
    if (
        float(observation["safety_confidence"]) < 0.60
        or float(observation["closing_risk"]) >= 0.75
    ):
        memory["state"] = "STOPPED"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Require stable target identity and use bounded, non-advancing reacquisition."""
    visible = bool(observation["target_visible"])
    reliable = (
        visible
        and float(observation["target_confidence"]) >= 0.55
        and float(observation["target_identity_confidence"]) >= 0.60
    )

    if not reliable:
        lost_steps = int(observation["lost_steps"])
        state = memory.get("state")
        if state in {"LOCKED", "APPROACH", "REACQUIRE"} and lost_steps <= 1:
            memory["state"] = "REACQUIRE"
            return "STOP", 0.92

        previous_lost = int(memory.get("previous_lost_steps", -1))
        direction = memory.get("scan_direction", "SCAN_LEFT")
        if lost_steps > previous_lost and lost_steps > 0:
            direction = "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
        memory["previous_lost_steps"] = lost_steps
        memory["scan_direction"] = direction
        memory["state"] = "SEARCH"
        return direction, 0.75

    memory["previous_lost_steps"] = 0
    if int(observation["track_age"]) < 2:
        memory["state"] = "VERIFY"
        return "SLOW_DOWN", 0.80
    return None


def propose_moves(observation, memory):
    """Generate corridor-valid moves with directional choices ahead of lateral extras."""
    bearing = float(observation["target_bearing"])
    candidates = []

    if bearing < -12.0 and bool(observation["corridor_left"]):
        candidates.append("VEER_LEFT")
    if bearing > 12.0 and bool(observation["corridor_right"]):
        candidates.append("VEER_RIGHT")
    if bool(observation["corridor_center"]):
        candidates.append("FORWARD")
    if bool(observation["corridor_left"]):
        candidates.append("VEER_LEFT")
    if bool(observation["corridor_right"]):
        candidates.append("VEER_RIGHT")

    return list(dict.fromkeys(candidates))


def progress_contract(observation, memory, candidates):
    """Choose the best valid move using bearing utility and one-step hysteresis."""
    if not candidates:
        return None

    bearing = float(observation["target_bearing"])
    previous = memory.get("last_action")
    previous_bearing = memory.get("last_bearing")
    stagnation = int(memory.get("stagnation", 0))

    def utility(action):
        if action == "VEER_LEFT":
            value = max(0.0, -bearing)
        elif action == "VEER_RIGHT":
            value = max(0.0, bearing)
        else:
            value = max(0.0, 20.0 - abs(bearing))

        if previous == action:
            value += 4.0
        if previous in {"VEER_LEFT", "VEER_RIGHT"} and action in {
            "VEER_LEFT",
            "VEER_RIGHT",
        } and previous != action:
            value -= 7.0
        if (
            previous == action
            and previous_bearing is not None
            and abs(bearing) <= abs(float(previous_bearing))
        ):
            value += 3.0
        if stagnation >= 2 and action == previous:
            value -= 2.0
        return value

    action = max(candidates, key=utility)
    if previous == action and previous_bearing is not None:
        improving = abs(bearing) < abs(float(previous_bearing)) - 1.0
        memory["stagnation"] = 0 if improving else min(stagnation + 1, 3)
    else:
        memory["stagnation"] = 0

    memory["last_action"] = action
    memory["last_bearing"] = bearing
    return action


def termination_contract(observation, memory):
    """Return a safe stationary fallback whenever no movement is admissible."""
    memory["state"] = "STOPPED"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination contracts."""
    memory = dict(memory or {})

    safety = safety_contract(observation, memory)
    if safety is not None:
        return safety[0], safety[1], memory

    tracking = tracking_contract(observation, memory)
    if tracking is not None:
        return tracking[0], tracking[1], memory

    memory["state"] = "LOCKED"
    if observation["target_distance_class"] == "near":
        aligned = (
            abs(float(observation["heading_error"])) <= 15.0
            and float(observation["target_identity_confidence"]) >= 0.80
        )
        if aligned:
            memory["state"] = "ARRIVED"
            memory["last_action"] = "ARRIVED"
            return "ARRIVED", 0.96, memory

        bearing = float(observation["target_bearing"])
        candidates = [
            "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory

    memory["state"] = "APPROACH"
    return action, 0.90, memory


# EVOLVE-BLOCK-END
